package org.brightstats.desktop;

import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.stage.Window;
import org.brightstats.stats.*;

final class GroupDialog {
    record Membership(PlsGroups.Selection selection,String source){Membership{Objects.requireNonNull(selection);if(source==null)source="Explicit prepared-row selection";}void validate(int rows){for(int[] group:List.of(selection.rowsA(),selection.rowsB()))for(int row:group)if(row>=rows)throw new IllegalArgumentException("SEM group row is outside the prepared data.");}}
    record Settings(PlsGroups.Selection selection,boolean consistent,PlsPermutation.Options permutation,Bootstrap.Options bootstrap,boolean retained,String membershipSource){
        Settings{Objects.requireNonNull(selection);Objects.requireNonNull(permutation);Objects.requireNonNull(bootstrap);if(membershipSource==null)membershipSource="Explicit prepared-row selection";}
        void validate(int rows){for(int[] group:List.of(selection.rowsA(),selection.rowsB()))for(int row:group)if(row>=rows)throw new IllegalArgumentException("A saved group row is outside the prepared dataset.");}
    }
    private final Dialog<Settings> dialog=new Dialog<>();private final TextField nameA=new TextField(),nameB=new TextField(),rowsA=new TextField(),rowsB=new TextField(),samples=new TextField(),seed=new TextField(),level=new TextField();private final CheckBox consistent=new CheckBox("Use consistent PLS (PLSc) in every group/refit"),retain=new CheckBox("Retain individual sample values in saved numeric results"),configural=new CheckBox("I have verified identical indicator coding, model specification and estimator settings across groups"),oneTail=new CheckBox("One-tailed reference convention");private final ComboBox<RegressionBootstrap.Convention> convention=new ComboBox<>();private final ComboBox<BootstrapIntervals.Method> interval=new ComboBox<>();private final ComboBox<String> source=new ComboBox<>();private final ListView<String> categoriesA=new ListView<>(),categoriesB=new ListView<>();private final Button apply=UiAppearance.button("Use selected categories for groups");private String membershipSource;private Settings settings;
    private GroupDialog(Window owner,int observations,Map<String,List<String>> grouping,Settings previous,boolean permutation){this(owner,observations,grouping,previous,permutation,false);}
    private GroupDialog(Window owner,int observations,Map<String,List<String>> grouping,Settings previous,boolean permutation,boolean membershipOnly){
        dialog.initOwner(owner);dialog.setTitle(membershipOnly?"Select SEM groups":permutation?"Group permutation and MICOM":"Bootstrap multigroup analysis");dialog.setResizable(true);var permutationOptions=previous==null?PlsPermutation.Options.defaults():previous.permutation();var bootstrap=previous==null?new Bootstrap.Options(5000,42,.95):previous.bootstrap();
        nameA.setText(previous==null?"Group A":previous.selection().nameA());nameB.setText(previous==null?"Group B":previous.selection().nameB());rowsA.setText(previous==null?"":formatRows(previous.selection().rowsA()));rowsB.setText(previous==null?"":formatRows(previous.selection().rowsB()));rowsA.textProperty().addListener((o,a,b)->membershipSource="Explicit prepared-row selection");rowsB.textProperty().addListener((o,a,b)->membershipSource="Explicit prepared-row selection");membershipSource=previous==null?"Explicit prepared-row selection":previous.membershipSource();consistent.setSelected(previous!=null&&previous.consistent());retain.setSelected(previous!=null&&previous.retained());configural.setSelected(permutationOptions.configuralConfirmed());configural.disableProperty().bind(consistent.selectedProperty());consistent.setVisible(!membershipOnly);consistent.setManaged(!membershipOnly);configural.setVisible(!membershipOnly);configural.setManaged(!membershipOnly);
        Label explanation=UiAppearance.label("Select two disjoint groups in the prepared analysis data. Original source columns use retained-row mappings, so removed rows are not accidentally reassigned. Alternatively enter one-based prepared row numbers/ranges, such as 1-40, 45. Rows outside both groups are excluded and reported.");explanation.setWrapText(true);VBox groups=new VBox(8,explanation,UiAppearance.label("Group A name"),nameA,UiAppearance.label("Group A prepared rows"),rowsA,UiAppearance.label("Group B name"),nameB,UiAppearance.label("Group B prepared rows"),rowsB,consistent,configural);groups.setPadding(new Insets(12));
        source.getItems().setAll(grouping.keySet());categoriesA.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);categoriesB.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);categoriesA.setPrefHeight(140);categoriesB.setPrefHeight(140);source.valueProperty().addListener((o,a,b)->{List<String> levels=grouping.containsKey(b)?grouping.get(b).stream().filter(v->!v.isBlank()).distinct().sorted().toList():List.of();categoriesA.getItems().setAll(levels);categoriesB.getItems().setAll(levels);});apply.setDisable(grouping.isEmpty());apply.setOnAction(event->{if(source.getValue()==null)return;List<String> a=List.copyOf(categoriesA.getSelectionModel().getSelectedItems()),b=List.copyOf(categoriesB.getSelectionModel().getSelectedItems()),labels=grouping.get(source.getValue());int[] first=java.util.stream.IntStream.range(0,labels.size()).filter(i->a.contains(labels.get(i))).toArray(),second=java.util.stream.IntStream.range(0,labels.size()).filter(i->b.contains(labels.get(i))).toArray();rowsA.setText(formatRows(first));rowsB.setText(formatRows(second));membershipSource="Source column: "+source.getValue()+"; A="+a+"; B="+b;});VBox fromSource=new VBox(8,new Label(grouping.isEmpty()?"No retained categorical source column is available; enter explicit prepared rows on the Groups tab.":"Choose a retained source column and one or more categories per group."),source,UiAppearance.label("Group A categories"),categoriesA,UiAppearance.label("Group B categories"),categoriesB,apply);fromSource.setPadding(new Insets(12));
        samples.setText(Integer.toString(permutation?permutationOptions.samples():bootstrap.samples()));seed.setText(Long.toString(permutation?permutationOptions.seed():bootstrap.seed()));level.setText(Double.toString(permutation?permutationOptions.significance():bootstrap.confidence()));convention.getItems().setAll(RegressionBootstrap.Convention.values());convention.setValue(permutation?permutationOptions.convention():bootstrap.convention());oneTail.setSelected(permutation?!permutationOptions.twoSided():!bootstrap.twoSided());oneTail.setDisable(convention.getValue()==RegressionBootstrap.Convention.STANDARD);convention.valueProperty().addListener((o,a,b)->{oneTail.setDisable(b==RegressionBootstrap.Convention.STANDARD);if(b==RegressionBootstrap.Convention.STANDARD)oneTail.setSelected(false);});interval.getItems().setAll(BootstrapIntervals.Method.values());interval.setValue(bootstrap.interval());VBox inference=new VBox(8,UiAppearance.label("Fixed attempts"),samples,UiAppearance.label("Random seed"),seed,new Label(permutation?"Significance level (e.g. 0.05)":"Confidence (e.g. 0.95)"),level,UiAppearance.label("Sampling and inference convention"),convention,oneTail,retain);if(!permutation)inference.getChildren().addAll(UiAppearance.label("Group-specific confidence interval"),interval);inference.setPadding(new Insets(12));TabPane tabs=new TabPane(new Tab("Groups",groups),new Tab("Source categories",fromSource),new Tab("Inference",inference));if(membershipOnly)tabs.getTabs().remove(2);for(var tab:tabs.getTabs())tab.setClosable(false);Label error=new Label();error.setWrapText(true);VBox content=new VBox(8,tabs,error);content.setPadding(new Insets(12));content.setPrefSize(680,620);dialog.getDialogPane().setContent(content);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);
        dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{settings=null;try{var selection=new PlsGroups.Selection(nameA.getText().trim(),nameB.getText().trim(),parseRows(rowsA.getText(),observations),parseRows(rowsB.getText(),observations));if(membershipOnly){settings=new Settings(selection,previous!=null&&previous.consistent(),permutationOptions,bootstrap,previous!=null&&previous.retained(),membershipSource);settings.validate(observations);return;}int count=Integer.parseInt(samples.getText().trim());long chosenSeed=Long.parseLong(seed.getText().trim());double chosenLevel=Double.parseDouble(level.getText().trim());var permute=permutation?new PlsPermutation.Options(count,chosenSeed,chosenLevel,convention.getValue(),!oneTail.isSelected(),retain.isSelected(),configural.isSelected()):permutationOptions;var boot=permutation?bootstrap:new Bootstrap.Options(count,chosenSeed,chosenLevel,interval.getValue(),convention.getValue(),!oneTail.isSelected());settings=new Settings(selection,consistent.isSelected(),permute,boot,retain.isSelected(),membershipSource);settings.validate(observations);}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?settings:null);
    }
    static int[] parseRows(String text,int observations){if(text==null||text.isBlank())throw new IllegalArgumentException("Choose rows for both groups.");Set<Integer> rows=new TreeSet<>();for(String item:text.split(",",-1)){String[] ends=item.trim().split("-",-1);if(ends.length<1||ends.length>2)throw new IllegalArgumentException("Use row numbers or increasing ranges.");int first=Integer.parseInt(ends[0].trim()),last=ends.length==1?first:Integer.parseInt(ends[1].trim());if(first<1||last<first||last>observations)throw new IllegalArgumentException("Group rows must be within 1–"+observations+".");for(int i=first;i<=last;i++)if(!rows.add(i-1))throw new IllegalArgumentException("A row is repeated within a group.");}return rows.stream().mapToInt(Integer::intValue).toArray();}
    static String formatRows(int[] rows){if(rows.length==0)return "";int[] sorted=rows.clone();Arrays.sort(sorted);List<String> ranges=new ArrayList<>();for(int i=0;i<sorted.length;){int start=sorted[i],end=start;while(++i<sorted.length&&sorted[i]==end+1)end=sorted[i];ranges.add(start==end?Integer.toString(start+1):(start+1)+"-"+(end+1));}return String.join(", ",ranges);}
    static Optional<Settings> show(Window owner,int rows,Map<String,List<String>> grouping,Settings previous,boolean permutation){return new GroupDialog(owner,rows,grouping,previous,permutation).dialog.showAndWait();}
    static Optional<Membership> showMembership(Window owner,int rows,Map<String,List<String>> grouping,Membership previous){Settings settings=previous==null?null:new Settings(previous.selection(),false,PlsPermutation.Options.defaults(),new Bootstrap.Options(5000,42,.95),false,previous.source());return new GroupDialog(owner,rows,grouping,settings,false,true).dialog.showAndWait().map(value->new Membership(value.selection(),value.membershipSource()));}
    static Membership readMembership(com.google.gson.JsonElement input,int rows){var selection=input.getAsJsonObject().getAsJsonObject("selection");for(String key:List.of("rowsA","rowsB"))for(var value:selection.getAsJsonArray(key))value.getAsBigDecimal().intValueExact();var membership=new com.google.gson.Gson().fromJson(input,Membership.class);membership.validate(rows);return membership;}
    static Membership smokeMembership(Window owner,int observations){var test=new GroupDialog(owner,observations,Map.of(),null,false,true);test.dialog.show();test.rowsA.setText("1-3");test.rowsB.setText("3-6");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Invalid SEM memberships accepted");test.rowsA.setText("1-"+(observations/2));test.rowsB.setText((observations/2+1)+"-"+observations);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("SEM membership lost");return new Membership(test.settings.selection(),test.settings.membershipSource());}
    static Settings read(com.google.gson.JsonElement input,int rows){var object=input.getAsJsonObject();var selection=object.getAsJsonObject("selection");for(String key:List.of("rowsA","rowsB"))for(var value:selection.getAsJsonArray(key))value.getAsBigDecimal().intValueExact();for(String key:List.of("permutation","bootstrap")){var options=object.getAsJsonObject(key);options.get("samples").getAsBigDecimal().intValueExact();options.get("seed").getAsBigDecimal().longValueExact();}var settings=new com.google.gson.Gson().fromJson(object,Settings.class);settings.validate(rows);return settings;}
    static Settings smokeTest(Window owner,int observations,boolean permutation,Settings previous){Map<String,List<String>> grouping=Map.of("Synthetic category",java.util.stream.IntStream.range(0,observations).mapToObj(i->i<observations/2?"A":"B").toList());var test=new GroupDialog(owner,observations,grouping,previous,permutation);test.dialog.show();test.rowsA.setText("1-3");test.rowsB.setText("3-6");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Overlapping groups accepted");test.source.getSelectionModel().selectFirst();test.categoriesA.getSelectionModel().select("A");test.categoriesB.getSelectionModel().select("B");test.apply.fire();if(parseRows(test.rowsA.getText(),observations).length!=observations/2||!test.membershipSource.startsWith("Source column:"))throw new AssertionError("Category group mapping failed");test.samples.setText("29");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Invalid group resampling count accepted");test.samples.setText("40");test.configural.setSelected(true);test.retain.setSelected(true);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("Group settings lost");var malformed=new com.google.gson.Gson().toJsonTree(test.dialog.getResult()).getAsJsonObject();malformed.getAsJsonObject("selection").getAsJsonArray("rowsA").set(0,new com.google.gson.JsonPrimitive(.5));try{read(malformed,observations);throw new AssertionError("Fractional saved group row accepted");}catch(ArithmeticException expected){}return test.dialog.getResult();}
}
